const isOcean16=()=>S?.mapId==='ocean';
function polygon16(p,poly){let hit=false;for(let i=0,j=poly.length-1;i<poly.length;j=i++){let a=poly[i],b=poly[j];if((a[1]>p.y)!==(b[1]>p.y)&&p.x<(b[0]-a[0])*(p.y-a[1])/(b[1]-a[1])+a[0])hit=!hit;}return hit;}
function lake16(p){return ATLAS_MAPS.ocean.lakes.some(e=>inEllipse(p,e));}
function land16(p){return polygon16(p,ATLAS_MAPS.ocean.coast)&&!lake16(p);}
function shore16(p){let poly=ATLAS_MAPS.ocean.coast,best={d:Infinity};for(let i=1;i<poly.length;i++){let a=poly[i-1],b=poly[i],dx=b[0]-a[0],dy=b[1]-a[1],t=Math.max(0,Math.min(1,((p.x-a[0])*dx+(p.y-a[1])*dy)/(dx*dx+dy*dy))),x=a[0]+dx*t,y=a[1]+dy*t,d=Math.hypot(x-p.x,y-p.y);if(d<best.d)best={d,x,y,dx,dy};}return best;}
function spans16(a,b,test){let n=Math.max(8,Math.ceil(Math.hypot(a.x-b.x,a.y-b.y)/12)),out=[],start=null;for(let i=0;i<=n;i++){let t=i/n,hit=test({x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t});if(hit&&start===null)start=Math.max(0,(i-.5)/n);if(!hit&&start!==null){out.push([start,(i-.5)/n]);start=null;}}if(start!==null)out.push([start,1]);return out;}
const buildableBefore16=cityBuildable;
cityBuildable=function(x,y,size=0){if(mapSpec.id!=='ocean')return buildableBefore16(x,y,size);let p={x,y};return land16(p)&&y>120&&shore16(p).d>42&&mountainDistance(p)>48&&ATLAS_MAPS.ocean.lakes.every(e=>!inEllipse(p,{...e,rx:e.rx+50,ry:e.ry+50}));};
