riverDistance=function(p){return mapSpec.id!=='ocean'?distanceBefore16(p):Math.min(...ATLAS_MAPS.ocean.lakes.map(e=>Math.abs(Math.hypot((p.x-e.x)/e.rx,(p.y-e.y)/e.ry)-1)*Math.min(e.rx,e.ry)));};
const requirementsBefore16=requirements;
