const bridgeIssueBefore16=bridgeTerrainIssue;
bridgeTerrainIssue=function(a,b){if(mapSpec.id!=='ocean')return bridgeIssueBefore16(a,b);if(!a||!b)return '请选择两个桥头';if(!land16(a)||!land16(b)||spans16(a,b,p=>!polygon16(p,ATLAS_MAPS.ocean.coast)).length)return '海洋禁止建桥，五大湖可建桥';if(Math.hypot(a.x-b.x,a.y-b.y)>260)return '桥过长';if(spans16(a,b,lake16).length!==1)return '桥应连接湖泊两岸';return mountainCrossings(a,b).length?'桥位穿山':null;};
const snapBefore16=snapBank;
snapBank=function(p){if(mapSpec.id!=='ocean')return snapBefore16(p);let e=ATLAS_MAPS.ocean.lakes.reduce((a,b)=>Math.abs(Math.hypot((p.x-a.x)/a.rx,(p.y-a.y)/a.ry)-1)<Math.abs(Math.hypot((p.x-b.x)/b.rx,(p.y-b.y)/b.ry)-1)?a:b),ang=Math.atan2((p.y-e.y)/e.ry,(p.x-e.x)/e.rx);return {x:e.x+Math.cos(ang)*(e.rx+20),y:e.y+Math.sin(ang)*(e.ry+20),side:1};};
const activateBefore16=activateAtlasGeometry;
activateAtlasGeometry=function(id){let r=activateBefore16(id);if(id==='ocean'){activeAtlasMap=atlasClone(ATLAS_MAPS.ocean);mapSpec=activeAtlasMap;riverSegments.length=0;terrainCache=null;}if(typeof clearMarinePaths16==='function')clearMarinePaths16();return r;};
function cityDay16(n){return n<=3?0:n<=6?(n-3)*10:n<=12?30+(n-6)*8:n<=24?78+(n-12)*10:198+(n-24)*12;}
let spawnCandidates16=null;
function chooseCity16(){if(!spawnCandidates16){spawnCandidates16=[];for(let y=180;y<3300;y+=60)for(let x=60;x<3560;x+=60)if(cityBuildable(x,y,2))spawnCandidates16.push({x,y});}let cs=realCities(),n=cs.length+1,phase=n<=12?0:n<=24?1:2,candidates=spawnCandidates16.map(p=>({...p,near:Math.min(...cs.map(c=>Math.hypot(c.x-p.x,c.y-p.y))),coast:shore16(p).d})).filter(p=>p.near>=240&&p.near<=720&&p.y>=(phase===0?1800:phase===1?1050:150)&&cs.some(c=>{if(Math.hypot(c.x-p.x,c.y-p.y)>720)return false;for(let i=1;i<12;i++){let q={x:c.x+(p.x-c.x)*i/12,y:c.y+(p.y-c.y)*i/12};if(!polygon16(q,ATLAS_MAPS.ocean.coast)||lake16(q))return false;}return true;}));if(!candidates.length)return null;
 let groups=[candidates.filter(p=>p.coast<=150),candidates.filter(p=>p.coast>150&&p.y>=1200),candidates.filter(p=>p.coast>150&&p.y<1200)],weights=phase===0?[.8,.2,0]:phase===1?[.3,.65,.05]:[.25,.3,.45],available=groups.map((g,i)=>g.length?weights[i]:0),roll=Math.random()*available.reduce((a,b)=>a+b,0),group=groups.find((g,i)=>(roll-=available[i])<0)||candidates,ranked=group.map(p=>({...p,score:Math.random()*200+Math.abs(p.near-420)*.4})).sort((a,b)=>a.score-b.score);return ranked.find(p=>cs.some(c=>{if(Math.hypot(c.x-p.x,c.y-p.y)>720)return false;let r=requirements(c,p,'bus');return !r.invalid&&r.tunnel<=1&&r.bridge<=1;}))||null;}
const spawnBefore16=spawnCity;
spawnCity=function(){if(!isOcean16())return spawnBefore16();let n=realCities().length+1,target=cityDay16(n);if(S.day+1e-8<target||S.day<(S.map3RetryAt||0))return;let p=chooseCity16();if(!p){S.map3RetryAt=S.day+.5;return;}let c=addCity(p,cityRegions()[0]);Object.assign(c,{discoveredAt:target,regionId:0,remote:false,regionalGrowth:false});if(n===10)Object.assign(c,{name:'拉斯维加斯',shape:1,isVegas:true,art:'sphere'});growthState().next=cityDay16(n+1);S.map3RetryAt=0;save();};
const resetBefore16=reset;
reset=function(...a){let r=resetBefore16(...a);if(isOcean16()){S.points=STARTING_FUNDS.ocean;S.calendarOffset16=150;S.spawnDay=10;S.map3RetryAt=0;S.tutorial123=null;S.cityRegions=[{id:0,x:2595,y:2115,name:'双洋大陆',discoveredAt:0,nextLocalAt:Infinity}];S.atlasGrowth=null;spawnCandidates16=null;activateAtlasGeometry('ocean');ATLAS_MAPS.ocean.start.forEach((p,i)=>Object.assign(S.cities[i],{x:p[0],y:p[1],regionId:0,remote:false}));growthState().next=10;fit();}if(typeof migrate16==='function')migrate16();save();return r;};
const dateBefore16=formatDate;
formatDate=function(){if(!isOcean16())return dateBefore16();let elapsed=Math.floor(S.day),d=elapsed+150;return {d:elapsed,year:Math.floor(d/360)+1,month:Math.floor(d%360/30)+1,day:d%30+1,weekday:['周一','周二','周三','周四','周五','周六','周日'][elapsed%7]};};
const terrainBefore16=drawTerrain;
function paintOcean16(){let m=ATLAS_MAPS.ocean;ctx.fillStyle='#91becb';ctx.fillRect(-240,0,4140,3900);ctx.beginPath();m.coast.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fillStyle='#e6edda';ctx.fill();ctx.lineWidth=18;ctx.strokeStyle='#e1d8b7';ctx.stroke();ctx.lineWidth=3;ctx.strokeStyle='#6b9d9c';ctx.stroke();for(let e of m.hills)ellipse(e,'#cbd5af');for(let poly of mountainPolygons){ctx.beginPath();poly.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle='#9fb294';ctx.fill();}for(let e of m.mountains){let ridge=Array.from({length:8},(_,i)=>({x:e.x+Math.sin(i*1.8+e.y)*26,y:e.y-e.ry+i*e.ry*2/7}));for(let i=1;i<ridge.length;i++){let a=ridge[i-1],b=ridge[i],width=e.rx*(.7+.2*Math.sin(i*2.1));for(let side of [-1,1]){ctx.beginPath();ctx.moveTo(a.x,a.y-12);ctx.lineTo(b.x,b.y-17);ctx.lineTo(b.x+width*side,b.y+26);ctx.lineTo(a.x+width*.8*side,a.y+18);ctx.closePath();ctx.fillStyle=side<0?'#b8c7a4':'#8d9f84';ctx.fill();ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=1;ctx.stroke();}}}for(let e of m.lakes)ellipse(e,'#8dbfc7');for(let y=180;y<3150;y+=130)for(let x=120;x<3450;x+=135){let p={x:x+Math.sin(y*.1+x)*30,y:y+Math.cos(x*.03)*24};if(land16(p)&&shore16(p).d>65&&mountainDistance(p)>30&&Math.sin(x*.013+y*.027)>.35){artTree(p.x,p.y,.8,false);artTree(p.x+18,p.y+12,.6,false);}}}
drawTerrain=function(){if(mapSpec.id!=='ocean')return terrainBefore16();let b=ATLAS_MAPS.ocean.bounds,w=b.xmax-b.xmin,h=b.ymax-b.ymin;if(!terrainCache){let cache=document.createElement('canvas');cache.width=Math.ceil(w*.55);cache.height=Math.ceil(h*.55);let live=ctx;try{ctx=cache.getContext('2d');ctx.scale(.55,.55);ctx.translate(-b.xmin,-b.ymin);paintOcean16();terrainCache=cache;}finally{ctx=live;}}ctx.drawImage(terrainCache,b.xmin,b.ymin,w,h);};
function coldIntensity16(e,p){let t=Math.max(0,Math.min(1,(S.day-e.start)/(e.end-e.start))),front=e.north+(e.south-e.north)*t;return Math.max(0,1-Math.abs(p.y-front)/e.width)*(1-.85*t);}
const weatherBefore16=weatherFactor;
weatherFactor=function(p,type){if(!isOcean16())return weatherBefore16(p,type);let factor=1;for(let e of S.climate.events){if(S.day<e.start||S.day>=e.end)continue;if(e.type==='cold'){let strength=coldIntensity16(e,p);if(isMarine16(type))continue;if(type==='air'&&strength>.1)return 0;factor=Math.min(factor,1-strength*(type==='bus'?.4:type==='emu'?.22:type==='rail'?.16:.3)*(stationCoverage(p)?.5:1));}else{let c=weatherCenter(e);if(Math.hypot(p.x-c.x,p.y-c.y)>e.radius)continue;if(isMarine16(type)){if(e.type==='typhoon')factor=Math.min(factor,.9);continue;}if(e.type==='typhoon'&&type==='air')return 0;factor=Math.min(factor,1-(type==='bus'?.3:isTrain(type)?.12:.2)*(stationCoverage(p)?.5:1));}}return factor;};
const climateBefore16=updateClimate;
updateClimate=function(oldDay){if(!isOcean16())return climateBefore16(oldDay);let cl=S.climate,d=formatDate();cl.seasons??={};if(d.year>1&&!cl.seasons['ocean'+d.year]){let start=(d.year-1)*360+205-150;cl.seasons['ocean'+d.year]=true;let count=Math.random()<.5?3:4;for(let i=0;i<count;i++){let a=start+i*65/count+rand(0,Math.max(1,65/count-8));cl.events.push({id:'ocean-storm-'+d.year+'-'+i,type:'typhoon',strong:true,start:a,end:a+rand(5,7),radius:460,x:3100,y:3100,vx:-70,vy:-290});}}if(S.day>=cl.next){let c=pick(realCities());cl.events.push({type:Math.random()<.5?'rain':'fog',start:S.day+2,end:S.day+6,x:c.x,y:c.y,radius:400});cl.next=S.day+rand(14,22);}if((d.month===12||d.month<=2)&&Math.floor(S.day)>oldDay&&S.day>=(cl.nextCold16||0)){cl.events.push({id:'cold-'+Math.floor(S.day),type:'cold',start:S.day,end:Math.min(S.day+rand(4.8,7.2),(d.month===12?d.year*360+60:(d.year-1)*360+60)-150),north:150,south:3450,width:850});cl.nextCold16=S.day+rand(18,30);toast('寒潮自北向南移动 · 强度逐步减弱');}cl.events=cl.events.filter(e=>e.end>S.day);if(Math.floor(S.day)>oldDay&&S.day>=150&&S.unlocked.includes('rail')&&S.day-cl.lastQuake>=80&&realCities().filter(c=>!c.dormant).length>=6&&Math.random()<.008)triggerQuake();};
const climateDrawBefore16=drawClimate;
drawClimate=function(){if(!isOcean16())return climateDrawBefore16();let events=S.climate.events;S.climate.events=events.filter(e=>e.type!=='cold');try{climateDrawBefore16();}finally{S.climate.events=events;}for(let e of events.filter(e=>e.type==='cold'&&S.day>=e.start&&S.day<e.end)){let t=(S.day-e.start)/(e.end-e.start),y=e.north+(e.south-e.north)*t,g=ctx.createLinearGradient(0,y-e.width,0,y+e.width);g.addColorStop(0,'#d8eefb00');g.addColorStop(.5,'#b2d6eb55');g.addColorStop(1,'#d8eefb00');ctx.fillStyle=g;ctx.fillRect(0,y-e.width,3600,e.width*2);text('寒潮 · 强度 '+Math.round((1-.85*t)*100)+'%',1800,y-18,24,'#5a819a');}};
const cityArtBefore16=drawCityArt;
drawCityArt=function(c){if(!c.isVegas)return cityArtBefore16(c);ctx.save();ctx.translate(c.x,c.y-45);let r=24+c.size*8,g=ctx.createLinearGradient(-r,-r,r,r);g.addColorStop(0,'#faf0be');g.addColorStop(.45,COLORS[c.color]);g.addColorStop(1,'#415b70');ctx.fillStyle=g;ctx.beginPath();ctx.arc(0,0,r,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff9';ctx.lineWidth=1.5;for(let y=-r*.6;y<r;y+=r*.4){ctx.beginPath();ctx.ellipse(0,y,Math.sqrt(Math.max(0,r*r-y*y)),r*.12,0,0,Math.PI*2);ctx.stroke();}ctx.restore();};
const weatherPageBefore16=showWeather;
